theorem heq_path_of_eq_image : HEq ((πₘ f).map ⟦p⟧) ((πₘ g).map ⟦q⟧)  := by
  simp only [map_eq, ← Path.Homotopic.map_lift];
  apply Path.Homotopic.hpath_hext;
  exact hfg

